UPDATE _ludolab_schema_tmp SET s = s || '{"locale":"it","nx_ui_lang":"it","nx_choice_cards":true,"goNextPageAutomatic":true,"allowCompleteSurveyAutomatic":false,"nx_shuffle_blocks":true,"nx_shuffle_within":["test","grcs"],"nx_section_format":"Parte {k} di {n}: {title}","nx_speed_consecutive":3,"showProgressBar":"off","showQuestionNumbers":"off","questionsOnPageMode":"standard","requiredText":"*","pagePrevText":"Indietro","pageNextText":"Avanti","completeText":"Invia le risposte","nx_paradata":true,"nx_speed_prompt":true,"nx_speed_ms_per_word":350,"calculatedValues":[{"name":"forma_test","expression":"iif({cod_cifra} anyof [''0'', ''2'', ''4'', ''6'', ''8''], ''A'', ''B'')","includeIntoResult":true},{"name":"versione_vignette","includeIntoResult":true,"expression":"iif({cod_mese} anyof [''01'', ''03'', ''05'', ''07'', ''09'', ''11''], ''1'', ''2'')"}],"pages":[{"name":"p001_qd01","elements":[{"type":"html","name":"qd01","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Questa ricerca vuole capire che cosa pensa chi ha la tua età dei giochi in cui si puntano soldi (scommesse, gratta e vinci) e degli acquisti a sorpresa nei videogiochi.</p><p style=\"margin:0 0 6px;line-height:1.6;\">Puoi rispondere anche se non giochi.</p><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">Non è una verifica: niente voti.</strong></p></div><div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">È anonimo: non scrivere il tuo nome.</strong></p><p style=\"margin:0 0 6px;line-height:1.6;\">Solo i ricercatori leggono le risposte, mai insegnanti o genitori.</p></div><div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">Partecipare è libero: puoi saltare qualsiasi domanda o smettere quando vuoi, senza conseguenze.</strong></p></div><div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Alcune domande hanno una risposta giusta.</p><p style=\"margin:0 0 6px;line-height:1.6;\">Se non la sai, scegli «Non lo so»: va bene.</p></div><div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Ci vogliono circa 30 minuti.</p></div><div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Il questionario registra anche quanto tempo resti su ogni pagina e il tipo di schermo che usi: ci serve solo a capire se le domande sono troppo lunghe o difficili.</p></div>"},{"name":"consent_assenso","title":"Ho letto queste informazioni e voglio partecipare.","type":"boolean","renderAs":"checkbox","isRequired":true,"label":"Ho letto queste informazioni e voglio partecipare.","titleLocation":"hidden","requiredErrorText":"Questa risposta serve per andare avanti."},{"name":"impegno_iniziale","title":"Ti chiediamo di leggere ogni domanda e di rispondere con attenzione. Te la senti?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Sì, mi impegno"},{"value":2,"text":"No"}]}],"title":"Benvenuto, benvenuta"},{"name":"p002_cod_madre","elements":[{"type":"html","name":"stim_cod_madre","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Ora crea il tuo codice segreto: serve a collegare i tuoi questionari dei prossimi mesi senza che nessuno sappia chi sei.</p></div>"},{"name":"cod_madre","title":"Prima lettera del nome di tua madre (es. Laura → L)","type":"text","inputType":"text","maxLength":1,"autocomplete":"off","description":"Scrivi una sola lettera.","placeholder":"","maskType":"pattern","maskSettings":{"pattern":"a"},"validators":[{"type":"regex","regex":"^[A-Za-zÀ-ÖØ-öø-ÿ]$","text":"Scrivi una sola lettera."}],"isRequired":true,"requiredErrorText":"Questa risposta serve per andare avanti.","visibleIf":"({cod_madre_nonso} <> true)"},{"type":"boolean","name":"cod_madre_nonso","renderAs":"checkbox","titleLocation":"hidden","title":"Non la conosco","label":"Non la conosco"},{"name":"cod_padre","title":"Prima lettera del 