:"Scrivi una sola lettera."}],"isRequired":true,"requiredErrorText":"Questa risposta serve per andare avanti."}],"title":"Il tuo codice","nx_section_title":"Il tuo codice","nx_section_id":"codice","description":"Circa 1 minuto"},{"name":"p003_ctx03","elements":[{"type":"html","name":"stim_ctx03","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Alcune domande su di te.</p></div>"},{"name":"ctx03","title":"Genere: come ti descrivi?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Ragazza"},{"value":2,"text":"Ragazzo"},{"value":3,"text":"Non binario"},{"value":4,"text":"In un altro modo"},{"value":5,"text":"Preferisco non rispondere"}]}],"title":"Su di te","nx_section_title":"Su di te","nx_section_id":"contesto","description":"Circa 1 minuto"},{"name":"p004_ctx04","elements":[{"name":"ctx04","title":"In che anno sei nato o nata?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"2010 o dopo"},{"value":2,"text":"2009"},{"value":3,"text":"2008 o prima"}]}]},{"name":"p005_ctx05","elements":[{"name":"ctx05","title":"Sei nato o nata in Italia?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Sì"},{"value":2,"text":"No, in un altro Paese"}]}]},{"name":"p006_ctx06","elements":[{"name":"ctx06","title":"Dove sono nati i tuoi genitori?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"In Italia"},{"value":2,"text":"Uno in Italia e uno all''estero"},{"value":3,"text":"All''estero"},{"value":4,"text":"Non lo so"}]}]},{"name":"p007_ctx08","elements":[{"type":"html","name":"desc_ctx08","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">Di solito, quanto tempo al giorno giochi ai videogiochi (su telefono, console o computer)?</p><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\"><strong style=\"color:#286181\">Non contare i giochi con soldi veri.</strong></p></div>"},{"name":"ctx08","title":"In un giorno di scuola","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Per niente"},{"value":2,"text":"Circa mezz''ora"},{"value":3,"text":"Circa 1 ora"},{"value":4,"text":"2-3 ore"},{"value":5,"text":"4-5 ore"},{"value":6,"text":"6 ore o più"}]}]},{"name":"p008_ctx10","elements":[{"name":"ctx10","title":"Negli ultimi 12 mesi, quanto spesso i tuoi genitori, o altri adulti con cui vivi, hanno giocato soldi (lotterie, biglietti da grattare, scommesse, slot)? Pensa a chi gioca di più.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Mai"},{"value":2,"text":"Qualche volta all''anno"},{"value":3,"text":"Qualche volta al mese"},{"value":4,"text":"Qualche volta alla settimana"},{"value":5,"text":"Ogni giorno o quasi"},{"value":6,"text":"Non lo so"}]}]},{"name":"p009_cur01","elements":[{"type":"html","name":"stim_cur01","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Qui «scommettere» vuol dire <strong style=\"color:#286181\">puntare soldi veri sperando di vincerne di più</strong>: scommesse sulle partite, gratta e vinci, slot, poker o casinò online.</p><p style=\"margin:0 0 6px;line-height:1.6;\">A qualcuno le scommesse interessano, ad altri no: rispondi pensando a te, in questo periodo.</p></div>"},{"name":"cur01","title":"Per me, scommettere soldi veri è una cosa...","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Molto brutta"},{"value":2,"text":"Abbastanza brutta"},{"value":3,"text":"Né brutta né bella"},{"value":4,"text":"Abbastanza bella"},{"value":5,"text":"Molto bella"}]}],"nx_block":"opinioni","title":"Che cosa ne pensi","nx_section_title":"Che cosa ne pensi","nx_section_id":"opinioni","description":"Circa 2 minuti"},{"name":"p010_cur02","elements":[{"name":"cur02","title":"Per me, scommettere soldi veri è una cosa...","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Molto sgradevole"},{"value":2,"text":"Abbastanza sgradevole"},{"value":3,"text":"Né sgradevole né piacevole"},{"value":4,"text":"Abbastanza piacevole"},{"value":5,"text":"Molto piacevole"}]}],"nx_block":"opinioni"},{"name":"p011_cur03","elements":[{"name":"cur03","title":"Quanta curiosità ti fa l''idea di fare tu una scommessa con soldi veri?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Nessuna"},{"value":2,"text":"Poca"},{"value":3,"text":"Abbastanza"},{"value":4,"text":"Molta"},{"value":5,"text":"Moltissima"}]}],"nx_block":"opinioni"},{"name":"p012_cur04","elements":[{"name":"cur04","title":"Quanta voglia hai di fare una scommessa con soldi veri?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Nessuna"},{"value":2,"text":"Poca"},{"value":3,"text":"Abbastanza"},{"value":4,"text":"Molta"},{"value":5,"text":"Moltissima"}]}],"nx_block":"opinioni"},{"name":"p013_int01","elements":[{"type":"html","name":"desc_int01","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">Pensa ai prossimi 3 mesi, cioè fino a febbraio.</p><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">C&#x27;è chi fa queste cose e chi no: rispondi pensando a cosa farai davvero.</p><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\"><strong style=\"color:#286181\">Pensi che lo farai?</strong></p></div>"},{"name":"int01","title":"Giocare soldi veri per provare a vincerne altri (gratta e vinci, lotto, scommesse, slot machine, carte o poker con soldi), anche online.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Sicuramente no"},{"value":2,"text":"Probabilmente no"},{"value":3,"text":"Probabilmente sì"},{"value":4,"text":"Sicuramente sì"}]}],"nx_block":"opinioni"},{"name":"p014_int02","elements":[{"type":"html","name":"desc_int02","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">Pensa ai prossimi 3 mesi, cioè fino a febbraio.</p><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">C&#x27;è chi fa queste cose e chi no: rispondi pensando a cosa farai davvero.</p><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\"><strong style=\"color:#286181\">Pensi che lo farai?</strong></p></div>"},{"name":"int02","title":"Scommettere soldi su partite o gare sportive (per esempio una schedina sul calcio), per conto tuo o con altre persone, anche online.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Sicuramente no"},{"value":2,"text":"Probabilmente no"},{"value":3,"text":"Probabilmente sì"},{"value":4,"text":"Sicuramente sì"}]}],"nx_block":"opinioni"},{"name":"p015_istr_test","elements":[{"type":"html","name":"istr_test","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Ora leggerai alcune situazioni.</p><p style=\"margin:0 0 6px;line-height:1.6;\">In molte domande c&#x27;è una sola risposta giusta: scegli quella che ti sembra migliore.</p><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">Se non la sai, scegli «Non lo so».</strong></p></div>"}],"nx_block":"test","title":"Situazioni e scelte","nx_section_title":"Situazioni e scelte","nx_section_id":"test","description":"Circa 9 minuti","nx_block_fixed":true},{"name":"p016_tlt01a","elements":[{"type":"html","name":"stim_tlt01a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">A ogni estrazione del lotto escono 5 numeri su 90: ogni numero ha 1 probabilità su 18 di uscire. Il 47 non esce da 100 estrazioni di fila.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt01a","title":"Quanto è probabile che esca alla prossima estrazione?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Più del solito: dopo 100 estrazioni tocca a lui"},{"value":2,"text":"Quasi certo: in media esce una volta ogni 18"},{"value":3,"text":"Meno del solito: il lotto evita i numeri più giocati"},{"value":4,"text":"Come sempre, 1 su 18: il passato non conta"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p017_tlt02a","elements":[{"type":"html","name":"stim_tlt02a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Gioco online: 25 caselle, 3 bombe nascoste. Ogni casella senza bomba fa salire la vincita. Puoi incassare quando vuoi; se trovi una bomba, perdi la puntata. In media il sito restituisce 97 centesimi per euro puntato.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt02a","title":"Scegliendo quando fermarsi, che cosa può cambiare chi gioca?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Quanto spesso vince, non quanto perde in media"},{"value":2,"text":"Quanto perde in media: chi si ferma presto perde meno"},{"value":3,"text":"Molto: con la pratica si sente il momento giusto"},{"value":4,"text":"Niente: in questo gioco si perde sempre"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p018_tlt03a","elements":[{"type":"html","name":"stim_tlt03a","html":"<div style=\"margin:0 0 14p' WHERE id = '7310b128-af81-5094-9db9-36f0bc69fc98';
UPDATE _ludolab_schema_tmp SET s = s || 'x\"><p style=\"margin:0 0 6px;line-height:1.6;\">In un gratta e vinci si vincono 100.000 euro trovando tre corone. Su molti biglietti perdenti compaiono due corone e un altro simbolo. Elena ne ha appena grattato uno.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt03a","title":"Che cosa è vero su questi biglietti?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Sono perdite che sembrano quasi vincite"},{"value":2,"text":"Annunciano che la vincita grande è vicina"},{"value":3,"text":"Indicano che bisogna scegliere meglio il biglietto"},{"value":4,"text":"Servono a pagare meno vincite vere"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p019_tlt04a","elements":[{"type":"html","name":"stim_tlt04a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Kevin scommette online sul calcio virtuale: partite simulate al computer ogni tre minuti. Perde 30 euro e pensa: &#x27;Se smetto ora, li ho persi per sempre. Continuo finché torno in pari.&#x27;</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt04a","title":"Che cosa è vero sul piano di Kevin?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Ha senso: smettere vuol dire accettare la perdita"},{"value":2,"text":"Funziona, se a ogni perdita raddoppia la puntata"},{"value":3,"text":"Sbaglia solo il momento: meglio recuperare domani, con calma"},{"value":4,"text":"Anche le puntate per recuperare fanno perdere, in media"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p020_tlt05a","elements":[{"type":"html","name":"stim_tlt05a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un sito accetta scommesse su una partita di videogiochi tra due squadre. Chi indovina riceve 1,85 euro per ogni euro puntato. In tutto si puntano 1.000 euro: 500 su ciascuna squadra.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt05a","title":"Che cosa succede al sito dopo la partita?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Va in pari: metà vince e metà perde"},{"value":2,"text":"Guadagna o perde, secondo la squadra che vince"},{"value":3,"text":"Guadagna 75 euro, qualunque squadra vinca"},{"value":4,"text":"Guadagna 500 euro: tiene le puntate perdenti"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p021_tlt06a","elements":[{"type":"html","name":"stim_tlt06a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Su Instagram un casinò in criptovaluta promette: &#x27;Deposita 50 euro e te ne regaliamo altri 50!&#x27;. In piccolo: per ritirare il regalo devi prima puntare in tutto 2.000 euro.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt06a","title":"Per il casinò, a cosa serve questa offerta?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"A farti giocare senza rischiare i tuoi soldi"},{"value":2,"text":"A farti puntare molto prima di poter ritirare"},{"value":3,"text":"A far credere a un regalo che non esiste"},{"value":4,"text":"A mettere un tetto a quanto puoi puntare in tutto"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p022_tlt07a","elements":[{"type":"html","name":"stim_tlt07a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un gioco per cellulare regala forzieri a chi entra nell&#x27;app. Si provano due versioni. Versione 1: un forziere ogni 7 accessi. Versione 2: il forziere arriva a caso, in media ogni 7 accessi.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt07a","title":"Con quale versione i giocatori entrano più spesso?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Con la 2: non sapere quando arriva fa riprovare"},{"value":2,"text":"Con la 1: sapere quando arriva il premio motiva"},{"value":3,"text":"Uguale: in media i premi sono gli stessi"},{"value":4,"text":"Con la 1: i premi regolari creano più dipendenza"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p023_tlt08a","elements":[{"type":"html","name":"stim_tlt08a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Sofia gioca a un videogioco di calcio sul cellulare. Perde cinque partite di fila e sta per chiudere l&#x27;app. Compare: &#x27;Solo per te! Pacchetto campioni a 1,99 euro invece di 9,99. Scade tra 15 minuti.&#x27;</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt08a","title":"Perché l''offerta arriva proprio adesso? Scegli il motivo più probabile.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"È un caso: le offerte arrivano a tutti"},{"value":2,"text":"Il gioco vede che vuole smettere e la trattiene"},{"value":3,"text":"Il gioco vuole vendere i suoi dati ad altre aziende"},{"value":4,"text":"Il gioco vuole aiutarla dopo tante sconfitte"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p024_tlt09a","elements":[{"type":"html","name":"stim_tlt09a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Uno streamer apre casse di skin in diretta su un sito a pagamento. Sullo schermo scorrono i nomi di chi, sul sito, ha appena trovato una skin rara.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt09a","title":"Su chi guarda, che effetto ha più spesso quella lista?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Nessuno: chi guarda non si lascia influenzare"},{"value":2,"text":"Allontana: si capisce che il sito è una truffa"},{"value":3,"text":"Fa sembrare facile vincere e spinge a provare"},{"value":4,"text":"Informa: mostra quanto spesso si vince"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p025_tlt10a","elements":[{"type":"html","name":"stim_tlt10a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un gioco per cellulare vende casse a sorpresa da 2 euro. Un&#x27;associazione di genitori chiede di aggiungere una sola regola per proteggere chi le compra.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tlt10a","title":"Quale di queste regole protegge di più?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Un avviso: ''Le casse possono creare dipendenza''"},{"value":2,"text":"Una cassa gratis dopo cinque senza premi rari"},{"value":3,"text":"Un tetto di spesa deciso prima e non alzabile"},{"value":4,"text":"Una lista dei premi rari trovati, per trasparenza"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p026_tlt01b","elements":[{"type":"html","name":"stim_tlt01b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">In un videogioco ogni cassa a sorpresa ha 1 probabilità su 50 di contenere un coltello raro. Luca ne ha aperte 120, senza mai trovarlo.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt01b","title":"Quanto è probabile che esca alla prossima cassa?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Come sempre, 1 su 50: il passato non conta"},{"value":2,"text":"Più del solito: dopo 120 casse tocca a lui"},{"value":3,"text":"Meno del solito: il gioco penalizza chi ne apre tante"},{"value":4,"text":"Quasi certo: in media esce una volta ogni 50"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p027_tlt02b","elements":[{"type":"html","name":"stim_tlt02b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Gioco online: un razzo decolla e la vincita si moltiplica, per 1,5, per 2, per 5... Puoi incassare quando vuoi; se il razzo esplode prima, perdi la puntata. In media il sito restituisce 96 centesimi per euro puntato.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt02b","title":"Scegliendo quando incassare, che cosa può cambiare chi gioca?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Molto: con la pratica si sente il momento giusto"},{"value":2,"text":"Quanto spesso vince, non quanto perde in media"},{"value":3,"text":"Niente: in questo gioco si perde sempre"},{"value":4,"text":"Quanto perde in media: chi incassa presto perde meno"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p028_tlt03b","elements":[{"type":"html","name":"stim_tlt03b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">In un gioco per cellulare ogni giro di ruota costa 50 gemme. Spesso la ruota rallenta e si ferma subito dopo lo spicchio del premio più grande. Ad Amira è appena successo.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt03b","title":"Che cosa è vero su questi giri?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Servono a dare meno premi grandi"},{"value":2,"text":"Sono perdite che sembrano quasi vincite"},{"value":3,"text":"Annunciano che il premio grande è vicino"},{"value":4,"text":"Indicano che bisogna scegliere meglio quando girare"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p029_tlt04b","elements":[{"type":"html","name":"stim_tlt04b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Giada compra gratta e vinci online da 5 euro, uno dopo l&#x27;altro. Perde 25 euro e pensa: &#x27;Se smetto ora, li ho persi per sempre. Continuo finché torno in pari.&#x27;</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt04b","title":"Che cosa è vero sul piano di Giada?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Sbaglia solo il momento: meglio recuperare domani, con calma"},{"value":2,"text":"Anche i biglietti per recuperare fanno perdere, in media"},{"value":3,"text":"Ha senso: smettere vuol dire accettare la perdita"},{"value":4,"text":"Funziona, se a ogni perdita compra biglietti più cari"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p030_tlt05b","elements":[{"type":"html","name":"stim_tlt05b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un casinò online lancia una moneta virtuale: si scommette su testa o croce. Chi indovina riceve 1,90 euro per ogni euro puntato. In tutto si puntano 800 euro: 400 su testa e 400 su croce.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt05b","title":"Che cosa succede al casinò dopo il lancio?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Va in pari: metà vince e metà perde"},{"value":2,"text":"Guadagna 400 euro: tiene le puntate perdenti"},{"value":3,"text":"Guadagna 40 euro, qualunque lato esca"},{"value":4,"text":"Guadagna o perde, secondo il lato che esce"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p031_tlt06b","elements":[{"type":"html","name":"stim_tlt06b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un&#x27;app di casinò online promette: &#x27;Prima ora senza rischi: se perdi, ti rimborsiamo fino a 30 euro!&#x27;. In piccolo: il rimborso è un bonus da puntare 10 volte prima di ritirarlo.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt06b","title":"Per l''app, a cosa serve questa offerta?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"A mettere un tetto a quanto puoi perdere in un''ora"},{"value":2,"text":"A far credere a un rimborso che non esiste"},{"value":3,"text":"A farti giocare senza rischiare i tuoi soldi"},{"value":4,"text":"A farti puntare ancora dopo che hai perso"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p032_tlt07b","elements":[{"type":"html","name":"stim_tlt07b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un videogioco online regala skin a chi gioca. Si provano due versioni. Versione 1: una skin ogni 10 partite. Versione 2: la skin arriva a caso, in media ogni 10 partite.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt07b","title":"Con quale versione si giocano più partite?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Con la 1: i premi regolari creano più dipendenza"},{"value":2,"text":"Uguale: in media i premi sono gli stessi"},{"value":3,"text":"Con la 2: non sapere quando arriva fa riprovare"},{"value":4,"text":"Con la 1: sapere quando arriva il premio motiva"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p033_tlt08b","elements":[{"type":"html","name":"stim_tlt08b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Marco gioca su un&#x27;app di casinò online. Perde 60 euro e chiude l&#x27;app. Dieci minuti dopo arriva una notifica: &#x27;Marco, la fortuna sta per girare! 20 giri gratis solo per te, fino a mezzanotte.&#x27;</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt08b","title":"Perché la notifica arriva proprio adesso? Scegli il motivo più probabile.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"L''app vuole aiutarlo a rifarsi della perdita"},{"value":2,"text":"È un caso: le notifiche arrivano a tutti"},{"value":3,"text":"L''app vuole vendere i suoi dati ad altre aziende"},{"value":4,"text":"L''app vede che ha smesso e prova a richiamarlo"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p034_tlt09b","elements":[{"type":"html","name":"stim_tlt09b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un canale Telegram di pronostici pubblica ogni giorno le foto delle schedine vincenti dei suoi iscritti, con la scritta: &#x27;Altri 15 vincitori oggi! Entra nel gruppo VIP.&#x27;</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt09b","title":"Su chi legge, che effetto hanno più spesso quelle foto?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Informano: mostrano quanto spesso si vince"},{"value":2,"text":"Allontanano: si capisce che il canale è una truffa"},{"value":3,"text":"Nessuno: chi legge non si lascia influenzare"},{"value":4,"text":"Fanno sembrare facile vincere e spingono a provare"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p035_tlt10b","elements":[{"type":"html","name":"stim_tlt10b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Un&#x27;autorità prepara nuove regole per i casinò online. Vuole aggiungerne una sola per proteggere chi gioca e ne sta valutando quattro.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tlt10b","title":"Quale di queste regole protegge di più?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Un limite di perdita deciso prima e non alzabile"},{"v' WHERE id = '7310b128-af81-5094-9db9-36f0bc69fc98';
UPDATE _ludolab_schema_tmp SET s = s || 'alue":2,"text":"Un bonus di consolazione dopo tre perdite di fila"},{"value":3,"text":"Un avviso: ''Il gioco può creare dipendenza''"},{"value":4,"text":"Un elenco delle ultime vincite, per trasparenza"},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p036_tla01a","elements":[{"type":"html","name":"stim_tla01a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">In Flip 7 le carte pescate non tornano nel mazzo; in Ready Set Bet si lanciano due dadi. A metà mazzo sono già usciti quasi tutti i 12; con i dadi, la somma 8 non esce da 10 lanci.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tla01a","title":"Rispetto a prima, quanto è probabile pescare un 12? E fare 8 con i dadi?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"12: come prima. Somma 8: più probabile."},{"value":2,"text":"12: meno probabile. Somma 8: come prima."},{"value":3,"text":"12: come prima. Somma 8: come prima."},{"value":4,"text":"12: meno probabile. Somma 8: più probabile."},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p037_tla03a","elements":[{"type":"html","name":"stim_tla03a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">In Flip 7 chi raccoglie 7 numeri diversi prende un bonus; chi pesca un numero che ha già perde tutti i punti del turno. Ale ha 6 numeri diversi, pesca un doppione e resta a zero. «C&#x27;ero quasi!», dice.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tla03a","title":"Come va considerato questo turno di Ale?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Una perdita come tutte le altre."},{"value":2,"text":"Un segno che sta migliorando."},{"value":3,"text":"Mezza vittoria: meglio di altre perdite."},{"value":4,"text":"Un segnale che il bonus è vicino."},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p038_tla08a","elements":[{"type":"html","name":"stim_tla08a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">In un laboratorio, un gruppo di studenti modifica Ready Set Bet, un gioco di scommesse su corse di cavalli a dadi, per renderlo meno dannoso. Il gruppo discute quattro regole.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"name":"tla08a","title":"Quale regola protegge di più chi gioca?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Ognuno fissa prima quanto può perdere."},{"value":2,"text":"Sul tabellone c''è scritto «Gioca responsabilmente»."},{"value":3,"text":"Chi perde tre volte riceve gettoni per rifarsi."},{"value":4,"text":"Tutti partono con gli stessi gettoni."},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"test"},{"name":"p039_tla01b","elements":[{"type":"html","name":"stim_tla01b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">In Flip 7 le carte pescate non tornano nel mazzo; in Can&#x27;t Stop si lanciano quattro dadi e certe combinazioni fanno «sballare». A metà mazzo sono già usciti quasi tutti gli 11; con i dadi, nella stessa situazione, non si sballa da 6 lanci.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tla01b","title":"Rispetto a prima, quanto è probabile pescare un 11? E sballare?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"11: come prima. Sballare: più probabile."},{"value":2,"text":"11: come prima. Sballare: come prima."},{"value":3,"text":"11: meno probabile. Sballare: come prima."},{"value":4,"text":"11: meno probabile. Sballare: più probabile."},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p040_tla03b","elements":[{"type":"html","name":"stim_tla03b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">In Ready Set Bet si scommette su cavalli che avanzano con la somma di due dadi. Bea ha puntato sul cavallo 6, che si ferma a una casella dal traguardo: vince il 7. «C&#x27;ero quasi!», dice Bea.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tla03b","title":"Come va considerata questa scommessa di Bea?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Un segnale che la vincita è vicina."},{"value":2,"text":"Mezza vittoria: meglio di altre perdite."},{"value":3,"text":"Un segno che sta migliorando."},{"value":4,"text":"Una scommessa persa come le altre."},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p041_tla08b","elements":[{"type":"html","name":"stim_tla08b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Alcuni studenti cambiano le regole di Ready Set Bet, un gioco di scommesse su corse di cavalli a dadi, perché faccia meno danni a chi gioca. Propongono quattro regole.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"name":"tla08b","title":"Quale regola protegge di più chi gioca?","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Chi perde riceve una scommessa gratis."},{"value":2,"text":"Prima di ogni corsa si legge «Divertiti con moderazione»."},{"value":3,"text":"Ogni tre corse c''è una pausa obbligatoria."},{"value":4,"text":"Tutti hanno lo stesso tempo per scommettere."},{"value":5,"text":"Non lo so"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"test"},{"name":"p042_vde02a","elements":[{"type":"html","name":"img_vde02a","html":"<img src=\"/images/research/ludolab/VDE02A.webp\" alt=\"Un uomo seduto al tavolo di cucina guarda al computer un gioco con un dado.\" width=\"1200\" height=\"800\" loading=\"lazy\" style=\"display:block;width:100%;max-width:560px;height:auto;border-radius:8px;margin:0 auto 12px\">","visibleIf":"({forma_test} = ''A'')"},{"type":"html","name":"desc_vde02a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">Ogni storia racconta una scelta e come è finita. Giudica la scelta in base a quello che la persona sapeva quando ha deciso.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"type":"html","name":"stim1_vde02a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Marco ha 25 anni. Su un sito di giochi autorizzato paga 5 euro per tirare un dado: se esce il 6 (1 volta su 6) riceve 20 euro, se no niente. Esce il 6 e Marco riceve 20 euro.</p></div>","visibleIf":"({forma_test} = ''A'') and ({versione_vignette} = ''1'')"},{"type":"html","name":"stim2_vde02a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Marco ha 25 anni. Su un sito di giochi autorizzato paga 5 euro per tirare un dado: se esce il 6 (1 volta su 6) riceve 20 euro, se no niente. Esce il 3 e Marco non riceve niente.</p></div>","visibleIf":"({forma_test} = ''A'') and ({versione_vignette} = ''2'')"},{"name":"vde02a","title":"La scelta di Marco di giocare era:","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Molto sbagliata"},{"value":2,"text":"Abbastanza sbagliata"},{"value":3,"text":"Né giusta né sbagliata"},{"value":4,"text":"Abbastanza giusta"},{"value":5,"text":"Molto giusta"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"vignette1","title":"Una storia da giudicare","nx_section_title":"Una storia da giudicare","nx_section_id":"vignette1","description":"Circa 1 minuto"},{"name":"p043_vde02b","elements":[{"type":"html","name":"img_vde02b","html":"<img src=\"/images/research/ludolab/VDE02B.webp\" alt=\"Un uomo sul divano guarda sul telefono una ruota divisa in sei parti.\" width=\"1200\" height=\"800\" loading=\"lazy\" style=\"display:block;width:100%;max-width:560px;height:auto;border-radius:8px;margin:0 auto 12px\">","visibleIf":"({forma_test} = ''B'')"},{"type":"html","name":"desc_vde02b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">Ogni storia racconta una scelta e come è finita. Giudica la scelta in base a quello che la persona sapeva quando ha deciso.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"type":"html","name":"stim1_vde02b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Luca ha 24 anni. Su un&#x27;app di giochi autorizzata paga 4 euro per girare una ruota con 6 parti: se esce quella vincente (1 volta su 6) riceve 16 euro, se no niente. Esce la parte vincente e Luca riceve 16 euro.</p></div>","visibleIf":"({forma_test} = ''B'') and ({versione_vignette} = ''1'')"},{"type":"html","name":"stim2_vde02b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Luca ha 24 anni. Su un&#x27;app di giochi autorizzata paga 4 euro per girare una ruota con 6 parti: se esce quella vincente (1 volta su 6) riceve 16 euro, se no niente. Esce una parte perdente e Luca non riceve niente.</p></div>","visibleIf":"({forma_test} = ''B'') and ({versione_vignette} = ''2'')"},{"name":"vde02b","title":"La scelta di Luca di giocare era:","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Molto sbagliata"},{"value":2,"text":"Abbastanza sbagliata"},{"value":3,"text":"Né giusta né sbagliata"},{"value":4,"text":"Abbastanza giusta"},{"value":5,"text":"Molto giusta"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"vignette1","title":"Una storia da giudicare","nx_section_title":"Una storia da giudicare","nx_section_id":"vignette1","description":"Circa 1 minuto"},{"name":"p044_vde04a","elements":[{"type":"html","name":"img_vde04a","html":"<img src=\"/images/research/ludolab/VDE04A.webp\" alt=\"Una donna in tabaccheria riceve dal tabaccaio un biglietto da grattare.\" width=\"1200\" height=\"800\" loading=\"lazy\" style=\"display:block;width:100%;max-width:560px;height:auto;border-radius:8px;margin:0 auto 12px\">","visibleIf":"({forma_test} = ''A'')"},{"type":"html","name":"desc_vde04a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">Ogni storia racconta una scelta e come è finita. Giudica la scelta in base a quello che la persona sapeva quando ha deciso.</p></div>","visibleIf":"({forma_test} = ''A'')"},{"type":"html","name":"stim1_vde04a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Giulia ha 22 anni. In tabaccheria compra un biglietto da grattare da 5 euro. Sul retro c&#x27;è scritto che 1 biglietto su 6 vince 20 euro, gli altri niente. Giulia gratta e non vince niente.</p></div>","visibleIf":"({forma_test} = ''A'') and ({versione_vignette} = ''1'')"},{"type":"html","name":"stim2_vde04a","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Giulia ha 22 anni. In tabaccheria compra un biglietto da grattare da 5 euro. Sul retro c&#x27;è scritto che 1 biglietto su 6 vince 20 euro, gli altri niente. Giulia gratta e vince 20 euro.</p></div>","visibleIf":"({forma_test} = ''A'') and ({versione_vignette} = ''2'')"},{"name":"vde04a","title":"La scelta di Giulia di comprare il biglietto era:","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Molto sbagliata"},{"value":2,"text":"Abbastanza sbagliata"},{"value":3,"text":"Né giusta né sbagliata"},{"value":4,"text":"Abbastanza giusta"},{"value":5,"text":"Molto giusta"}],"visibleIf":"({forma_test} = ''A'')"}],"nx_block":"vignette2","title":"Una storia da giudicare","nx_section_title":"Una storia da giudicare","nx_section_id":"vignette2","description":"Circa 1 minuto"},{"name":"p045_vde04b","elements":[{"type":"html","name":"img_vde04b","html":"<img src=\"/images/research/ludolab/VDE04B.webp\" alt=\"Una donna in tabaccheria consegna al tabaccaio una schedina.\" width=\"1200\" height=\"800\" loading=\"lazy\" style=\"display:block;width:100%;max-width:560px;height:auto;border-radius:8px;margin:0 auto 12px\">","visibleIf":"({forma_test} = ''B'')"},{"type":"html","name":"desc_vde04b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;color:#4a5560;font-size:0.95em\">Ogni storia racconta una scelta e come è finita. Giudica la scelta in base a quello che la persona sapeva quando ha deciso.</p></div>","visibleIf":"({forma_test} = ''B'')"},{"type":"html","name":"stim1_vde04b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Elena ha 30 anni. In tabaccheria fa una giocata da 4 euro a un gioco a estrazione. Sul cartello c&#x27;è scritto che 1 giocata su 6 vince 16 euro, le altre niente. Elena aspetta l&#x27;estrazione e non vince niente.</p></div>","visibleIf":"({forma_test} = ''B'') and ({versione_vignette} = ''1'')"},{"type":"html","name":"stim2_vde04b","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Elena ha 30 anni. In tabaccheria fa una giocata da 4 euro a un gioco a estrazione. Sul cartello c&#x27;è scritto che 1 giocata su 6 vince 16 euro, le altre niente. Elena aspetta l&#x27;estrazione e vince 16 euro.</p></div>","visibleIf":"({forma_test} = ''B'') and ({versione_vignette} = ''2'')"},{"name":"vde04b","title":"La scelta di Elena di giocare era:","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Molto sbagliata"},{"value":2,"text":"Abbastanza sbagliata"},{"value":3,"text":"Né giusta né sbagliata"},{"value":4,"text":"Abbastanza giusta"},{"value":5,"text":"Molto giusta"}],"visibleIf":"({forma_test} = ''B'')"}],"nx_block":"vignette2","title":"Una storia da giudicare","nx_section_title":"Una storia da giudicare","nx_section_id":"vignette2","description":"Circa 1 minuto"},{"name":"p046_istr_grcs","elements":[{"type":"html","name":"istr_grcs","html":"<div style=\"margin:0 0 14px\"><p style=\"margin:0 0 6px;line-height:1.6;\">Qui trovi alcune frasi sul gioco d&#x27;azzardo.</p><p style=\"margin:0 0 6px;line-height:1.6;\">Per ognuna indica quanto sei d&#x27;accordo.</p><p style=\"margin:0 0 6px;line-height:1.6;\"><strong style=\"color:#286181\">Non ci sono risposte giuste o sbagliate.</strong></p><p style=\"margin:0 0 6px;line-height:1.6;\">Se non hai mai giocato d&#x27;azzardo, rispondi pensando a come la vedi tu.</p></div>"}],"nx_block":"grcs","title":"Pensieri sul gioco","nx_section_title":"Pensieri sul gioco","nx_section_id":"grcs","description":"Circa 3 minuti","nx_block_fixed":true},{"name":"p047_grcs03","elements":[{"name":"grcs03","title":"Pregare mi aiuta a vincere.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Del tutto in disaccordo"},{"value":2,"text":"Moderatamente in disaccordo"},{"value":3,"text":"Leggermente in disaccordo"},{"value":4,"text":"Né d''accordo né in disaccordo"},{"value":5,"text":"Leggermente d''accordo"},{"value":6,"text":"Moderatamente d''accordo"},{"value":7,"text":"Del tutto d''accordo"}]}],"nx_block":"grcs"},{"name":"p048_grcs04","elements":[{"name":"grcs04","title":"Dopo le perdite al gioco arriva per forza una serie di vincite.","type":"radiogroup","colCount":1,"choices":[{"value":1,"text":"Del tutto in disaccordo"},{"value":2,"text":"Moderatamente in disaccordo"},{"value":3,"text":"Leggermente in disaccordo"},{"value":4,"text":"Né d''ac' WHERE id = '7310b128-af81-5094-9db9-36f0bc69fc98';
